def transform_grid(grid):
    from collections import Counter
    # Determine background (most common color)
    all_colors = Counter()
    for row in grid:
        for val in row:
            all_colors[val] += 1
    bg = max(all_colors, key=all_colors.get)

    def find_components(grid, val):
        H, W = len(grid), len(grid[0])
        visited = set()
        components = []
        for r in range(H):
            for c in range(W):
                if grid[r][c] == val and (r, c) not in visited:
                    comp = []
                    stack = [(r, c)]
                    visited.add((r, c))
                    while stack:
                        cr, cc = stack.pop()
                        comp.append((cr, cc))
                        for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < H and 0 <= nc < W:
                                if grid[nr][nc] == val and (nr, nc) not in visited:
                                    visited.add((nr, nc))
                                    stack.append((nr, nc))
                    components.append(comp)
        return components

    output = [[bg for _ in range(len(grid[0]))] for _ in range(len(grid))]

    non_bg_colors = set()
    for row in grid:
        for val in row:
            if val != bg:
                non_bg_colors.add(val)

    # Apply transform: fill bboxes for components with size >= 3
    for color in non_bg_colors:
        comps = find_components(grid, color)
        for comp in comps:
